create table if not exists future_phase15_approval_packages (id uuid primary key default gen_random_uuid(), status text not null default 'draft', legal_character text not null, policy_version text not null, schema_version text not null, source_manifest_id uuid, created_at timestamptz not null default now());
create table if not exists creator_interop_organizations (id uuid primary key default gen_random_uuid(), approval_package_id uuid references future_phase15_approval_packages(id), legal_character text not null, public_name text not null, status text not null default 'proposed', effective_at timestamptz, suspended_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now());
create table if not exists creator_interop_constitutive_instruments (id uuid primary key default gen_random_uuid(), organization_id uuid references creator_interop_organizations(id), version text not null, status text not null, authentic_languages text[] not null default '{}', content_hash text not null, effective_at timestamptz, supersedes_id uuid, created_at timestamptz not null default now());
create table if not exists creator_interop_participant_authorities (id uuid primary key default gen_random_uuid(), participant_external_ref text not null, participant_class text not null, authority_type text not null, instrument_hash text not null, jurisdiction text not null, effective_at timestamptz, expires_at timestamptz, suspended_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now());
create table if not exists creator_interop_memberships (id uuid primary key default gen_random_uuid(), organization_id uuid references creator_interop_organizations(id), participant_authority_id uuid references creator_interop_participant_authorities(id), state text not null, instrument_deposited_at timestamptz, effective_at timestamptz, withdrawal_effective_at timestamptz, policy_version text not null, audit_event_id uuid, created_at timestamptz not null default now());
